const CACHE_NAME="makoti-traders-v1";self.addEventListener("install",e=>{e.waitUntil(caches.open(CACHE_NAME).then(e=>e.addAll(["./","./manifest.webmanifest"])).then(()=>self.skipWaiting()))}),self.addEventListener("activate",e=>{e.waitUntil(caches.keys().then(e=>Promise.all(e.filter(e=>e!==CACHE_NAME).map(e=>caches.delete(e)))).then(()=>self.clients.claim()))}),self.addEventListener("fetch",e=>{let{request:t}=e;if("GET"===t.method&&new URL(t.url).origin===self.location.origin){if("navigate"===t.mode)return void e.respondWith(fetch(t).then(e=>{if(200===e.status){let n=e.clone();caches.open(CACHE_NAME).then(e=>e.put(t,n)).catch(()=>{})}return e}).catch(()=>caches.match(t).then(e=>e||caches.match("./"))));e.respondWith(caches.match(t).then(e=>e||fetch(t).then(e=>{if(200===e.status){let n=e.clone();caches.open(CACHE_NAME).then(e=>e.put(t,n)).catch(()=>{})}return e})))}});